#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


# Configuração única da assinatura do APK de produção (docs/mobile-release.md).
# Gera a keystore de release fora do repositório e grava os quatro secrets que o
# workflow .github/workflows/android-release.yml usa. Rodar de novo reaproveita a
# keystore existente e só regrava os secrets.
#
# Outra conta do gh: GH_TOKEN="$(gh auth token -u <conta>)" scripts/android-release-keystore.sh

TOTAL_STAGES=6

export GH_REPO="prisma-web/Clube-do-Jogo"
# Nada aqui vai para .env: senhas da keystore só existem no gerenciador de senhas e nos secrets.
ENV_FILE="/nonexistent/clube-do-jogo-wizard.env"
REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd -P)"
DEFAULT_KEYSTORE="$HOME/.config/clube-do-jogo/android-release.keystore"

banner "Keystore de release do Android · $GH_REPO"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Ferramentas e conta do GitHub"
for tool in keytool gh base64; do
  if ! command -v "$tool" >/dev/null 2>&1; then
    printf '  %s✗ falta %s no PATH%s\n' "$RED" "$tool" "$RESET"
    exit 1
  fi
done
if ! gh auth status >/dev/null 2>&1; then
  warn "o gh não está autenticado. Rode gh auth login e abra o wizard de novo."
  exit 1
fi
GH_LOGIN="$(gh api user --jq .login)"
say "Os secrets vão para $GH_REPO usando a conta ${BOLD}$GH_LOGIN${RESET}."
note "Para usar outra conta: GH_TOKEN=\"\$(gh auth token -u <conta>)\" $0"
confirm "Continuar com $GH_LOGIN?" || exit 1

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Onde guardar a keystore"
say "A keystore fica fora do repositório. Sugestão: $DEFAULT_KEYSTORE"
ask KEYSTORE_PATH "Caminho da keystore [Enter usa a sugestão]:"
KEYSTORE_PATH="${KEYSTORE_PATH:-$DEFAULT_KEYSTORE}"
KEYSTORE_PATH="${KEYSTORE_PATH/#\~/$HOME}"
mkdir -p "$(dirname "$KEYSTORE_PATH")"
KEYSTORE_PATH="$(cd "$(dirname "$KEYSTORE_PATH")" && pwd -P)/$(basename "$KEYSTORE_PATH")"
case "$KEYSTORE_PATH/" in
  "$REPO_ROOT"/*)
    printf '  %s✗ %s fica dentro do repositório. Escolha um caminho fora de %s.%s\n' "$RED" "$KEYSTORE_PATH" "$REPO_ROOT" "$RESET"
    exit 1
    ;;
esac
if [[ -e "$KEYSTORE_PATH" ]]; then
  say "Já existe uma keystore em $KEYSTORE_PATH. Ela será reaproveitada, nunca sobrescrita."
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Alias e senha"
ask KEY_ALIAS "Alias da chave [Enter usa clube-do-jogo]:"
KEY_ALIAS="${KEY_ALIAS:-clube-do-jogo}"
note "A keystore é PKCS12, em que a senha da chave é a mesma da keystore."
while true; do
  ask_secret KEYSTORE_PASSWORD "Senha da keystore (6+ caracteres):"
  if [[ -e "$KEYSTORE_PATH" ]]; then break; fi
  if (( ${#KEYSTORE_PASSWORD} < 6 )); then warn "a senha precisa de pelo menos 6 caracteres."; continue; fi
  ask_secret KEYSTORE_PASSWORD_AGAIN "Repita a senha:"
  [[ "$KEYSTORE_PASSWORD" == "$KEYSTORE_PASSWORD_AGAIN" ]] && break
  warn "as senhas não conferem, tente de novo."
done
export KEYSTORE_PASSWORD

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Gerar a keystore"
if [[ -e "$KEYSTORE_PATH" ]]; then
  say "Conferindo se alias e senha abrem a keystore existente…"
else
  say "Vai gerar uma chave RSA 4096 válida por 10000 dias em $KEYSTORE_PATH."
  confirm "Gerar agora?" || exit 1
  keytool -genkeypair -noprompt \
    -storetype PKCS12 -keystore "$KEYSTORE_PATH" \
    -alias "$KEY_ALIAS" -keyalg RSA -keysize 4096 -validity 10000 \
    -dname "CN=Clube do Jogo, O=Clube do Jogo" \
    -storepass:env KEYSTORE_PASSWORD -keypass:env KEYSTORE_PASSWORD >/dev/null
  chmod 600 "$KEYSTORE_PATH"
fi
if ! FINGERPRINT="$(keytool -list -v -keystore "$KEYSTORE_PATH" -alias "$KEY_ALIAS" -storepass:env KEYSTORE_PASSWORD 2>/dev/null | grep -m1 'SHA256:' | sed 's/^[[:space:]]*//')"; then
  printf '  %s✗ alias ou senha não abrem %s.%s\n' "$RED" "$KEYSTORE_PATH" "$RESET"
  exit 1
fi
printf '  %s✓ keystore pronta%s %s\n' "$GREEN" "$RESET" "$KEYSTORE_PATH"
note "Certificado: $FINGERPRINT"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Backup"
warn "Sem esta keystore e a senha, nenhum APK novo instala por cima do atual."
warn "Perder qualquer uma das duas obriga cada membro a desinstalar e instalar de novo."
step "Guarde o arquivo $KEYSTORE_PATH num gerenciador de senhas ou cofre."
step "Guarde junto o alias ($KEY_ALIAS) e a senha."
note "O secret no GitHub não serve de backup: ele não pode ser lido de volta."
until confirm "O backup do arquivo, do alias e da senha está feito?"; do
  say "Faça o backup antes de seguir."
done

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Secrets do GitHub Actions"
say "Grava em $GH_REPO os secrets que o workflow android-release usa."
if ! SECRETS="$(gh secret list)"; then
  printf '  %s✗ não deu para listar os secrets de %s. Confira se a conta tem acesso de admin.%s\n' "$RED" "$GH_REPO" "$RESET"
  exit 1
fi
CONFIGURED="$SECRETS
$(gh variable list || true)"
if grep -qE '^ANDROID_KEYSTORE_BASE64[[:space:]]' <<<"$CONFIGURED"; then
  warn "Já existe ANDROID_KEYSTORE_BASE64. Trocar a keystore quebra a atualização de quem já instalou o APK."
fi
confirm "Gravar os quatro secrets agora?" || exit 1
set_secret ANDROID_KEYSTORE_BASE64 "$(base64 < "$KEYSTORE_PATH" | tr -d '\n')"
set_secret ANDROID_KEYSTORE_PASSWORD "$KEYSTORE_PASSWORD"
set_secret ANDROID_KEY_ALIAS "$KEY_ALIAS"
set_secret ANDROID_KEY_PASSWORD "$KEYSTORE_PASSWORD"
# O workflow também precisa destas variáveis (ou secrets) do repositório; o resumo lista as que faltam.
for name in EXPO_APPLICATION_ID EXPO_PUBLIC_SUPABASE_URL EXPO_PUBLIC_SUPABASE_PUBLISHABLE_KEY EXPO_PUBLIC_API_BASE_URL EXPO_PUBLIC_SITE_URL; do
  grep -qE "^${name}[[:space:]]" <<<"$CONFIGURED" || SKIPPED+=("variável $name do workflow: gh variable set $name -R $GH_REPO")
done

finish
